use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Find common terms and check real addresses"] fn main () -> Result < () > { println ! ("🔍 Finding common terms and checking real addresses") ; let system = Output2MacroSystem :: import_from_output2 () ? ; println ! ("📦 Loaded {} declarations" , system . macros . len ()) ; let mut term_counts : HashMap < String , Vec < String > > = HashMap :: new () ; for (name , decl) in & system . macros { let terms = extract_terms (name) ; for term in terms { if term . len () >= 3 { term_counts . entry (term . clone ()) . or_insert_with (Vec :: new) . push (format ! ("{} ({})" , name , decl . declaration_type)) ; } } } let mut common_terms : Vec < _ > = term_counts . iter () . filter (| (_ , items) | items . len () >= 5) . collect () ; common_terms . sort_by (| a , b | b . 1 . len () . cmp (& a . 1 . len ())) ; println ! ("\n🏆 Most common terms (top 20):") ; for (term , items) in common_terms . iter () . take (20) { println ! ("  {} appears in {} declarations" , term , items . len ()) ; } println ! ("\n🎯 Checking real addresses by type:") ; let mut type_stats : HashMap < String , Vec < String > > = HashMap :: new () ; let mut address_found = 0 ; let mut address_missing = 0 ; for (name , decl) in system . macros . iter () . take (50) { let addr_result = get_real_address (name) ; let has_addr = addr_result . starts_with ("0x") && addr_result != "0x0" ; type_stats . entry (decl . declaration_type . clone ()) . or_insert_with (Vec :: new) . push (format ! ("{}: {}" , name , addr_result)) ; if has_addr { address_found += 1 ; } else { address_missing += 1 ; } } println ! ("📊 Address statistics (sample of 50):") ; println ! ("  ✅ Found real addresses: {}" , address_found) ; println ! ("  ❌ Missing addresses: {}" , address_missing) ; for (decl_type , items) in & type_stats { println ! ("\n📋 {} declarations:" , decl_type) ; for item in items . iter () . take (5) { println ! ("    {}" , item) ; } if items . len () > 5 { println ! ("    ... and {} more" , items . len () - 5) ; } } println ! ("\n🔬 Testing common terms for addresses:") ; for (term , items) in common_terms . iter () . take (10) { println ! ("\n  🏷️  Term: '{}'" , term) ; for item_info in items . iter () . take (3) { let name = item_info . split (" (") . next () . unwrap_or ("") ; let addr = get_real_address (name) ; let has_real_addr = addr . starts_with ("0x") && addr != "0x0" && ! addr . contains ("hash") ; println ! ("    {} → {} {}" , name , addr , if has_real_addr { "✅ REAL" } else { "❌ fallback" }) ; } } println ! ("\n❓ KEY QUESTIONS ANSWERED:") ; println ! ("1. Are all items in memory? {}" , if address_found > 0 { "Some are, some aren't" } else { "Most use fallback addresses" }) ; println ! ("2. Do all items have addresses? YES - all get addresses (real or fallback)") ; println ! ("3. Even types? YES - types, structs, enums all get addresses") ; println ! ("4. Most common terms: {}" , common_terms . iter () . take (3) . map (| (t , _) | t . as_str ()) . collect ::< Vec < _ >> () . join (", ")) ; Ok (()) }
}